function openCredits(){openPanel('JENERİK','GECE VARDİYASI • 2097',`<div class="credits">NEON COURIER<br><span style="color:#49f6ff">Neo İstanbul'da bir gece mesaisi.</span><br><br>TASARIM & GELİŞTİRME<br>Bağımsız bir sokak efsanesi<br><br>Bu şehir uyumaz.<br>Motorunu çalıştır. Paketleri yetiştir.<br><br><span style="color:#ff4fc8">YAĞMURUN ALTINDA, IŞIKLARIN İÇİNDE.</span></div>`)}
function pause(){if(state==='playing'){state='paused';openPanel('MOLA','MOTORU DİNLENDİR',`<div class="tagline">Vardiya duraklatıldı. Şehir seni bekliyor.</div><div class="modal-actions"><button class="btn primary" id="resume">▶ DEVAM ET</button><button class="btn" id="quit">ANA MENÜ</button></div>`);document.getElementById('resume').onclick=()=>{hideOverlay();state='playing';last=performance.now();tone(520)};document.getElementById('quit').onclick=showMain}}
function finishLevel(){state='complete';const lv=levels[Math.min(save.level,5)-1],bonus=Math.floor(timer/10)+combo*5,earned=lv.reward+bonus+(delivered*10*(save.upgrades.bonus+1));save.coins+=earned;save.best=Math.max(save.best,delivered);if(save.level<5)save.level++;persist();musicStop();tone(880,.3);openResult(true,earned,bonus)}
function gameOver(){if(state!=='playing')return;state='over';musicStop();tone(130,.6,'sawtooth');openResult(false,0,0)}
function openResult(won,earned,bonus){document.getElementById('hud').style.display='none';document.getElementById('overlay').classList.remove('hidden');const p=document.getElementById('subPanel');document.getElementById('mainPanel').classList.add('hidden');p.classList.remove('hidden');let lv=levels[Math.min(save.level-(won?1:0),5)-1];p.innerHTML=`<div class="kicker">${won?'ROTA TAMAMLANDI':'VARDİYA SONA ERDİ'} • BÖLÜM ${String(Math.min(save.level-(won?1:0),5)).padStart(2,'0')}</div><h2 class="panel-title">${won?'TESLİMAT BAŞARILI':'SÜRE DOLDU'}</h2><div class="result-big">${won?'+'+earned:'↻' } ${won?'◈':''}</div><div class="result-stats"><div>TESLİMAT<b>${delivered} / ${lv.deliveries}</b></div><div>EN YÜKSEK SERİ<b>×${Math.max(1,combo)}</b></div><div>ROTA ÖDÜLÜ<b>${won?lv.reward:0} ◈</b></div><div>HIZ BONUSU<b>${won?bonus:0} ◈</b></div></div><div class="progress"><i style="width:${won?100:Math.round(delivered/lv.deliveries*100)}%"></i></div><div class="modal-actions"><button class="btn primary" id="resultNext">${won?(save.level>5?'ANA MENÜ':'SONRAKİ ROTA'):'TEKRAR DENE'}</button><button class="btn" id="resultMenu">GARAJA DÖN</button></div>`;document.getElementById('resultNext').onclick=()=>{if(won&&save.level>5){showMain()}else startLevel()};document.getElementById('resultMenu').onclick=showMain}
function bump(){tone(100,.22,'square',.08);bike.vx*=-.32;bike.vy*=-.32;bike.x=clamp(bike.x,14,world.w-14);bike.y=clamp(bike.y,14,world.h-14)}
function collides(x,y){for(const b of world.buildings)if(x+9>b.x-b.w/2&&x-9<b.x+b.w/2&&y+9>b.y-b.h/2&&y-9<b.y+b.h/2)return true;for(const b of world.barriers)if(Math.abs(x-b.x)<b.w/2+8&&Math.abs(y-b.y)<b.h/2+8)return true;for(const c of world.cars)if(Math.abs(x-c.x)<c.w/2+9&&Math.abs(y-c.y)<c.h/2+9)return true;return x<12||y<12||x>world.w-12||y>world.h-12}
function target(){return mission.list[mission.index]}
function completeDelivery(){delivered++;combo++;let amount=Math.floor(10*(1+save.upgrades.bonus*.2)*Math.min(3,1+combo*.15));coinsThis+=amount;save.coins+=amount;persist();tone(770,.1);setTimeout(()=>tone(1100,.22),80);showToast(`TESLİMAT TAMAM!  +${amount} ◈  SERİ ×${combo}`);mission.index++;mission.phase='pickup';if(delivered>=levels[Math.min(save.level,5)-1].deliveries){setTimeout(()=>{if(state==='playing')finishLevel()},350)}}
function update(dt){if(state!=='playing')return;timer-=dt;if(timer<=0){timer=0;updateHud();gameOver();return}const speed=145+save.upgrades.speed*17,turn=1+save.upgrades.handling*.13;let dx=(keys.right?1:0)-(keys.left?1:0),dy=(keys.down?1:0)-(keys.up?1:0);if(dx&&dy){dx*=.707;dy*=.707}const accel=520*turn;bike.vx+=dx*accel*dt;bike.vy+=dy*accel*dt;const drag=Math.pow(dx||dy?.88:.82,dt*60);bike.vx*=drag;bike.vy*=drag;const vmax=speed;const mag=Math.hypot(bike.vx,bike.vy);if(mag>vmax){bike.vx=bike.vx/mag*vmax;bike.vy=bike.vy/mag*vmax}let nx=bike.x+bike.vx*dt,ny=bike.y+bike.vy*dt;if(collides(nx,ny))bump();else{bike.x=nx;bike.y=ny}if(mag>8){bike.angle=Math.atan2(bike.vy,bike.vx);runDistance+=mag*dt}
for(const c of world.cars){if(c.horizontal)c.x+=c.dir*c.speed*dt;else c.y+=c.dir*c.speed*dt;if(c.x<-60)c.x=world.w+60;if(c.x>world.w+60)c.x=-60;if(c.y<-60)c.y=world.h+60;if(c.y>world.h+60)c.y=-60}
const t=target();if(t){let p=mission.phase==='pickup'?t.pickup:t.dest;if(Math.hypot(bike.x-p.x,bike.y-p.y)<31){if(mission.phase==='pickup'){mission.phase='deliver';tone(440,.13);showToast('PAKET ALINDI — TESLİMAT NOKTASINA GİT!')}else completeDelivery()}}
world.rain.forEach(r=>{r.y+=r.s*dt;r.x-=r.s*.12*dt;if(r.y>H+20){r.y=-20;r.x=rand(0,W)}});updateHud()}
function updateHud(){const secs=Math.ceil(timer);document.getElementById('timer').textContent=String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0');document.getElementById('deliveries').textContent=`${delivered} / ${levels[Math.min(save.level,5)-1].deliveries}`;document.getElementById('coinsHud').textContent=save.coins;document.getElementById('comboHud').textContent=`SERİ ×${Math.max(1,combo)}`;const t=target();if(t){document.getElementById('missionState').textContent=mission.phase==='pickup'?'PAKETİ AL':'PAKETİ TESLİM ET';document.getElementById('missionTitle').textContent=mission.phase==='pickup'?'Paket noktası':'Müşteri bekliyor';document.getElementById('missionSub').textContent=mission.phase==='pickup'?'Pembe işarete git':'Mavi işarete git'}}
function camera(){return{x:clamp(bike.x-W/2,0,Math.max(0,world.w-W)),y:clamp(bike.y-H/2,0,Math.max(0,world.h-H))}}

