function camera(){return{x:clamp(bike.x-W/2,0,Math.max(0,world.w-W)),y:clamp(bike.y-H/2,0,Math.max(0,world.h-H))}}
function drawWorld(){const cam=camera();ctx.save();ctx.translate(-cam.x,-cam.y);ctx.fillStyle='#111321';ctx.fillRect(cam.x,cam.y,W,H);
// Asphalt grid and luminous lane markings
ctx.fillStyle='#171a27';ctx.fillRect(0,0,world.w,world.h);
const n=levels[Math.min(save.level,5)-1].grid;for(let i=0;i<=n;i++){let xs=i===0?0:i===n?ROAD+n*CELL-ROADW/2:ROAD+i*CELL-ROADW/2;let xe=i===0?ROADW/2:i===n?world.w:xs+ROADW;ctx.fillStyle='#1b1c2a';ctx.fillRect(xs,0,xe-xs,world.h);let ys=xs,ye=xe;ctx.fillRect(0,ys,world.w,ye-ys);ctx.strokeStyle='#4b4a63';ctx.lineWidth=2;ctx.setLineDash([18,21]);ctx.beginPath();ctx.moveTo((xs+xe)/2,0);ctx.lineTo((xs+xe)/2,world.h);ctx.moveTo(0,(ys+ye)/2);ctx.lineTo(world.w,(ys+ye)/2);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#32d8ef22';ctx.lineWidth=4;ctx.strokeRect(xs+3,0,xe-xs-6,world.h);ctx.strokeRect(0,ys+3,world.w,ye-ys-6)}
// buildings, rooftop details, windows
for(const b of world.buildings){if(b.x+b.w/2<cam.x-20||b.x-b.w/2>cam.x+W+20||b.y+b.h/2<cam.y-20||b.y-b.h/2>cam.y+H+20)continue;ctx.fillStyle='#0b0c18';ctx.fillRect(b.x-b.w/2-9,b.y-b.h/2-9,b.w+18,b.h+18);ctx.fillStyle='#18182a';ctx.fillRect(b.x-b.w/2,b.y-b.h/2,b.w,b.h);ctx.strokeStyle=`hsla(${b.hue},90%,65%,.8)`;ctx.lineWidth=2;ctx.strokeRect(b.x-b.w/2+5,b.y-b.h/2+5,b.w-10,b.h-10);ctx.fillStyle='#22233b';ctx.fillRect(b.x-b.w/2+13,b.y-b.h/2+13,b.w-26,b.h-26);for(let wx=b.x-b.w/2+22;wx<b.x+b.w/2-15;wx+=31){for(let wy=b.y-b.h/2+22;wy<b.y+b.h/2-15;wy+=29){let lit=Math.sin(wx*1.7+wy*3.1+b.seed*30)>.05;ctx.fillStyle=lit?`hsla(${b.hue},90%,65%,.58)`:'#0c1020';ctx.fillRect(wx,wy,8,7)}}ctx.fillStyle=`hsla(${b.hue},100%,65%,.1)`;ctx.fillRect(b.x-b.w/2+12,b.y-b.h/2+11,b.w-24,3);ctx.fillStyle='#25243b';ctx.fillRect(b.x-22,b.y-8,44,16);ctx.fillStyle=`hsla(${b.hue},95%,70%,.9)`;ctx.font='bold 9px monospace';ctx.textAlign='center';ctx.fillText(pick(['N-7','夜','24H','2097','NEO']),b.x,b.y+3)}
// glowing street lamps and reflections
for(let i=0;i<world.signs.length;i++){const s=world.signs[i];if(s.x<cam.x-50||s.x>cam.x+W+50||s.y<cam.y-50||s.y>cam.y+H+50)continue;ctx.globalAlpha=.16;ctx.fillStyle=s.color;ctx.beginPath();ctx.ellipse(s.x,s.y,30,10,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=s.color;ctx.fillRect(s.x-2,s.y-2,4,4)}
for(const c of world.cars){ctx.save();ctx.translate(c.x,c.y);if(!c.horizontal)ctx.rotate(Math.PI/2);ctx.shadowBlur=14;ctx.shadowColor=c.color;ctx.fillStyle='#10121e';ctx.fillRect(-c.w/2-2,-c.h/2-2,c.w+4,c.h+4);ctx.fillStyle=c.color;ctx.fillRect(-c.w/2,-c.h/2,c.w,c.h);ctx.fillStyle='#b9faff';ctx.fillRect(c.w/2-5,-c.h/2+2,3,3);ctx.fillRect(c.w/2-5,c.h/2-5,3,3);ctx.fillStyle='#252b3b';ctx.fillRect(-c.w/2+4,-c.h/2+2,c.w/2, c.h-4);ctx.restore()}
for(const b of world.barriers){ctx.save();ctx.translate(b.x,b.y);ctx.fillStyle='#141625';ctx.fillRect(-b.w/2,-b.h/2,b.w,b.h);ctx.fillStyle='#ffcb54';if(b.horizontal){for(let x=-b.w/2;x<b.w/2;x+=9)ctx.fillRect(x,-b.h/2,4,b.h)}else for(let y=-b.h/2;y<b.h/2;y+=9)ctx.fillRect(-b.w/2,y,b.w,4);ctx.restore()}
const t=target();if(t){let p=mission.phase==='pickup'?t.pickup:t.dest;let pulse=1+Math.sin(elapsed*5)*.15;ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=.22;ctx.fillStyle=mission.phase==='pickup'?'#ff4fc8':'#49f6ff';ctx.beginPath();ctx.arc(0,0,31*pulse,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=mission.phase==='pickup'?'#ff61d1':'#4cf7ff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,18*pulse,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#fff';ctx.fillRect(-5,-5,10,10);ctx.fillStyle=mission.phase==='pickup'?'#ff4fc8':'#49f6ff';ctx.font='bold 10px monospace';ctx.textAlign='center';ctx.fillText(mission.phase==='pickup'?'AL':'TESLİM',0,-27);ctx.restore()}
