--- index.html
+++ index.html
@@ -4,9 +4,9 @@
 <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><meta name="theme-color" content="#090914">
 <title>NEON COURIER — 2097</title>
 <style>
