const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const targets = await (await fetch('http://127.0.0.1:9223/json')).json();
  const page = targets.find(t => t.type === 'page');
  if (!page) throw new Error('No page target');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0;
  const pending = new Map();
  ws.onmessage = event => {
    const m = JSON.parse(event.data);
    if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
  };
  const send = (method, params = {}) => new Promise(resolve => {
    const callId = ++id;
    pending.set(callId, resolve);
    ws.send(JSON.stringify({id: callId, method, params}));
  });
  const evaluate = async expression => {
    const result = await send('Runtime.evaluate', {expression, awaitPromise: true, returnByValue: true});
    if (result.error) throw new Error(JSON.stringify(result.error));
    if (result.result.exceptionDetails) throw new Error(result.result.exceptionDetails.text);
    return result.result.result.value;
  };
  await send('Runtime.enable');
  await evaluate("document.getElementById('settingsBtn').click()");
  const settings = await evaluate("({shown:!document.getElementById('subPanel').classList.contains('hidden'),music:document.getElementById('musicToggle').checked,volume:+document.getElementById('volume').value})");
  await evaluate("document.getElementById('musicToggle').click();document.getElementById('volume').value=60;document.getElementById('volume').dispatchEvent(new Event('input',{bubbles:true}));document.querySelector('[data-close]').click()");
  await evaluate("localStorage.setItem('neonCourierSave',JSON.stringify({coins:150,level:1,upgrades:{speed:0,handling:0,bonus:0},best:0}));location.reload()");
  await sleep(600);
  await evaluate("document.getElementById('garageBtn').click()");
  await evaluate("document.querySelector('[data-buy=speed]').click()");
  const garage = await evaluate("({coins:JSON.parse(localStorage.getItem('neonCourierSave')).coins,speed:JSON.parse(localStorage.getItem('neonCourierSave')).upgrades.speed})");
  await evaluate("document.querySelector('[data-close]').click();document.getElementById('playBtn').click()");
  await sleep(300);
  const playing = await evaluate("({hud:getComputedStyle(document.getElementById('hud')).display,canvas:[document.getElementById('game').width,document.getElementById('game').height],world:document.getElementById('deliveries').textContent})");
  await evaluate("document.getElementById('pauseBtn').click()");
  const paused = await evaluate("document.getElementById('subPanel').innerText.includes('MOLA')");
  await evaluate("document.getElementById('resume').click();document.getElementById('pauseBtn').click();document.getElementById('quit').click()");
  console.log(JSON.stringify({settings,garage,playing,paused}, null, 2));
  ws.close();
})().catch(e => { console.error(e); process.exitCode = 1; });

