const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const page = (await (await fetch('http://127.0.0.1:9223/json')).json()).find(t => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0; const pending = new Map();
  ws.onmessage = e => {const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
  const send=(method,params={})=>new Promise(resolve=>{const callId=++id;pending.set(callId,resolve);ws.send(JSON.stringify({id:callId,method,params}))});
  const evaluate=async expression=>{const r=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result.exceptionDetails)throw new Error(r.result.exceptionDetails.text);return r.result.result.value};
  await send('Runtime.enable');
  await evaluate("localStorage.setItem('neonCourierSave',JSON.stringify({coins:0,level:1,upgrades:{speed:0,handling:0,bonus:0},best:0}));location.reload()"); await sleep(350);
  await evaluate("document.getElementById('playBtn').click();window.__test.setBike(window.__test.mission.list[0].pickup.x,window.__test.mission.list[0].pickup.y);window.__test.update(.016)");
  const pickup=await evaluate("({phase:window.__test.mission.phase,state:window.__test.state})");
  await evaluate("window.__test.setBike(window.__test.mission.list[0].dest.x,window.__test.mission.list[0].dest.y);window.__test.update(.016)");
  const delivery=await evaluate("({delivered:window.__test.delivered,coins:window.__test.save.coins,phase:window.__test.mission.phase})");
  const collision=await evaluate("({building:window.__test.collides(window.__test.bike.x,window.__test.bike.y),outside:window.__test.collides(-100,-100)})");
  await evaluate("window.__test.setTimer(.001);window.__test.update(.02)");
  const timeout=await evaluate("({state:window.__test.state,title:document.querySelector('#subPanel .panel-title').textContent,controlsHidden:document.getElementById('touch').classList.contains('hidden')})");
  await evaluate("document.getElementById('resultMenu').click();localStorage.setItem('neonCourierSave',JSON.stringify({coins:0,level:1,upgrades:{speed:0,handling:0,bonus:0},best:0}));document.getElementById('playBtn').click();window.__test.finishLevel()");
  const complete=await evaluate("({state:window.__test.state,level:window.__test.save.level,earned:window.__test.save.coins,title:document.querySelector('#subPanel .panel-title').textContent,deliveries:document.querySelector('.result-stats').innerText})");
  await evaluate("document.getElementById('resultMenu').click();window.__test.startLevel()");
  const touch=await evaluate("({visible:getComputedStyle(document.getElementById('touch')).display!=='none',count:document.querySelectorAll('#touch button').length})");
  await evaluate("document.getElementById('touch [data-dir=right]').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:5}));window.__test.update(.05)");
  const moving=await evaluate("({x:window.__test.bike.x,hidden:document.getElementById('touch').classList.contains('hidden')})");
  await evaluate("document.getElementById('touch [data-dir=right]').dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:5}));document.getElementById('pauseBtn').click();document.getElementById('quit').click();localStorage.removeItem('neonCourierSave')");
  console.log(JSON.stringify({pickup,delivery,collision,timeout,complete,touch,moving},null,2)); ws.close();
})().catch(e=>{console.error(e);process.exitCode=1});

