 function openCredits(){openPanel('JENERİK','GECE VARDİYASI • 2097',`<div class="credits">NEON COURIER<br><span style="color:#49f6ff">Neo İstanbul'da bir gece mesaisi.</span><br><br>TASARIM & GELİŞTİRME<br>Bağımsız bir sokak efsanesi<br><br>Bu şehir uyumaz.<br>Motorunu çalıştır. Paketleri yetiştir.<br><br><span style="color:#ff4fc8">YAĞMURUN ALTINDA, IŞIKLARIN İÇİNDE.</span></div>`)}
 function pause(){if(state==='playing'){state='paused';document.getElementById('overlay').classList.remove('hidden');openPanel('MOLA','MOTORU DİNLENDİR',`<div class="tagline">Vardiya duraklatıldı. Şehir seni bekliyor.</div><div class="modal-actions"><button class="btn primary" id="resume">▶ DEVAM ET</button><button class="btn" id="quit">ANA MENÜ</button></div>`);document.getElementById('resume').onclick=()=>{hideOverlay();state='playing';last=performance.now();tone(520)};document.getElementById('quit').onclick=showMain}}
